<script setup>
import {computed} from 'vue'
const props=defineProps({message:Object})
const names={general:'通用客服',technical:'技术支持',billing:'账单售后',escalation:'人工升级'}
const statusNames={completed:'已完成',degraded:'部分完成',failed:'执行未完成',not_run:'未调用',unknown:'未保存完整明细'}
const info=computed(()=>{const m=props.message;let state=m.agent_execution_status||'unknown',reason=m.processing_reason||'';if(!m.agent_execution_status){if(m.agent_outcomes?.length){state=m.execution_status||'unknown';reason='已保存各回复Agent的执行结果。'}else if(['no_match','unavailable','order_fact','record_reference','conversation_context'].includes(m.knowledge_status)){state='not_run';reason=['no_match','unavailable'].includes(m.knowledge_status)?'没有适用的可核对知识，使用记录整理与待核对信息，未执行回复Agent。':'直接核对本地记录或已有原话，未执行回复Agent。'}else if(m.manual){state='not_run';reason='人工撰写，未执行回复Agent。'}else reason='历史记录未保存完整执行明细，不能凭默认类型认定已调用。'}return {state,reason}})
</script>
<template><details class="reply-processing"><summary>回复Agent：{{statusNames[info.state]||info.state}}<span v-if="info.state!=='not_run'&&message.agent_outcomes?.length"> · {{[...new Set(message.agent_outcomes.map(o=>names[o.requested_agent]||o.requested_agent))].join('、')}}</span></summary><p>{{info.reason}}</p><ul v-if="message.agent_outcomes?.length"><li v-for="(o,i) in message.agent_outcomes" :key="i">{{names[o.requested_agent]||o.requested_agent}}：{{({completed:'已完成',fallback:'专属处理未完成，使用通用客服备用答复',failed:'执行失败或超时，需重试或人工核对'})[o.state]||o.state}}<span v-if="o.agent_type&&o.agent_type!==o.requested_agent">（实际处理：{{names[o.agent_type]||o.agent_type}}）</span></li></ul><p>此处只说明回复Agent；意图识别的模型请求另行统计。执行完成不代表答复正确或客户问题已解决。</p></details></template>
<style scoped>.reply-processing{margin:12px 0;padding:10px 12px;border:1px solid var(--border,#dbe1ec);border-radius:8px;color:var(--muted,#53627a);font-size:13px;line-height:1.6}.reply-processing summary{cursor:pointer;font-weight:600}.reply-processing p{margin:8px 0}.reply-processing ul{padding-left:20px}</style>
